  svg.appendChild(el("line",{x1:ex2,x2:ex2,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":0.5,"stroke-dasharray":"2,3"}));
  svg.appendChild(el("text",{x:ex2-45,y:MT+12,"text-anchor":"end","font-size":7,"font-weight":700,fill:"#1a3560"}, "PIPELINE SAOUDIEN"));
  svg.appendChild(el("text",{x:ex2-45,y:MT+22,"text-anchor":"end","font-size":7,"font-weight":700,fill:"#1a3560"}, "PÉTROLE +4,4\u00a0%"));
